part of '../site.dart';

const _te = SiteText(
  title: 'OpenCADIrrigation: AI తో కూడిన ఉచిత నీటిపారుదల డిజైన్ సాఫ్ట్‌వేర్',
  description: 'ఉచిత, ఓపెన్ సోర్స్ నీటిపారుదల డిజైన్ సాఫ్ట్‌వేర్: దీని AI అసిస్టెంట్ బ్రౌజర్‌లోనే స్ప్రింక్లర్లు, డ్రిప్ అమర్చి, పైపులు వేసి, వ్యవస్థ పరిమాణం నిర్ణయిస్తుంది.',
  keywords: 'AI నీటిపారుదల డిజైన్, AI నీటిపారుదల డిజైన్ సాఫ్ట్‌వేర్, ఆటోమేటిక్ నీటిపారుదల డిజైన్, ఆటోమేటిక్ స్ప్రింక్లర్ లేఅవుట్, నీటిపారుదల AI అసిస్టెంట్, నీటిపారుదల డిజైన్, నీటిపారుదల డిజైన్ సాఫ్ట్‌వేర్, ఓపెన్ సోర్స్ నీటిపారుదల సాఫ్ట్‌వేర్, నీటిపారుదల సాఫ్ట్‌వేర్, నీటిపారుదల CAD, పీడన నీటిపారుదల, బిందు సేద్యం, డ్రిప్ ఇరిగేషన్, మైక్రో స్ప్రింక్లర్, తుంపర సేద్యం, సెంటర్ పివట్, హైడ్రాలిక్ లెక్కలు, పైపు సైజింగ్, నీటిపారుదల ఏకరూపత, DXF, DWG, తోట నీటిపారుదల, వ్యవసాయ నీటిపారుదల, ఉచిత నీటిపారుదల సాఫ్ట్‌వేర్',
  h1: 'AI అసిస్టెంట్‌తో కూడిన ఉచిత, ఓపెన్ సోర్స్ నీటిపారుదల డిజైన్ సాఫ్ట్‌వేర్',
  tagline: 'పొలం, తోట లేదా మైదానాన్ని వివరించి, స్ప్రింక్లర్లు, డ్రిప్ లైన్లు అమర్చడం, పైపుల మార్గం వేయడం, వ్యవస్థ పరిమాణం నిర్ణయించడం AI అసిస్టెంట్‌కు వదిలేయండి; లేదా ఆటోమేటిక్ సాధనాలతో మీరే గీయండి. బిందు, మైక్రో స్ప్రింక్లర్, స్ప్రింక్లర్ మరియు సెంటర్ పివట్ వ్యవస్థలను నేరుగా బ్రౌజర్‌లోనే, ఏదీ ఇన్‌స్టాల్ చేయకుండా డిజైన్ చేయండి; మీ ప్రాజెక్టులు మీ సొంత కంప్యూటర్‌లోనే ఉంటాయి.',
  intro: 'OpenCADIrrigation CAD డ్రాయింగ్, హైడ్రాలిక్ నెట్‌వర్క్, లెక్కలు మరియు ఒక AI అసిస్టెంట్‌ను ఒకే చోటకు తెస్తుంది. ప్రాంతం సరిహద్దు గీయండి, లేదా ఉపగ్రహ చిత్రంలో స్థలాన్ని గుర్తించే పని AI కి అప్పగించండి; లేటరల్‌లు, వాల్వ్‌లు మరియు ప్రధాన లైన్‌ను స్వయంగా గానీ, ఒక్క క్లిక్‌తో పనిచేసే సాధనాలతో గానీ, AI ని అడిగి గానీ వేయండి; F5 నొక్కి పైపుల వ్యాసాలు, పీడనాలు, ఏకరూపత, నిర్వహణ షిఫ్టులు, సామగ్రి జాబితా మరియు ముద్రణకు సిద్ధమైన నివేదికలు పొందండి. అసిస్టెంట్ మీ సొంత API కీతో Claude (Anthropic) లేదా GPT (OpenAI) మోడల్‌లను నేరుగా బ్రౌజర్ నుండే వాడుతుంది. 20 భాషల్లో అందుబాటులో ఉంది, మీ కంప్యూటర్ భాషను అనుసరిస్తుంది.',
  openApp: 'యాప్ తెరవండి',
  tutorial: 'ఇంటరాక్టివ్ ట్యుటోరియల్',
  seeExamples: 'సిద్ధంగా ఉన్న ఉదాహరణలు చూడండి',
  aiTitle: 'మీతో కలిసి గీసి, డిజైన్ చేసే AI అసిస్టెంట్',
  aiIntro: 'డ్రాయింగ్ పక్కనే AI ప్యానెల్‌ను తెరిచి, మీ సొంత మాటల్లో అడగండి. అసిస్టెంట్ ప్రాజెక్టును చదువుతుంది, ఉపగ్రహ చిత్రాన్ని మరియు భూభాగాన్ని చూస్తుంది, మెనూలలోని అవే సాధనాలతో పనిచేస్తుంది; అందుకే అది గీసేది బొమ్మ కాదు, నిజమైన డిజైన్: అంశాలు, పైపులు, వాల్వ్‌లు, జోన్‌లు మరియు ఫలితాలు. ప్రతి మార్పు మీ ఆమోదం కోసం వేచి ఉంటుంది, లేదా మీరు కోరుకుంటే స్వయంచాలకంగా వర్తిస్తుంది; దాన్ని ఒక్క క్లిక్‌తో రద్దు చేయవచ్చు.',
  aiPoints: [
    (
      'ఆటోమేటిక్‌గా గీసి, డిజైన్ చేస్తుంది',
      'స్ప్రింక్లర్లను, డ్రిప్ లైన్లను అమరుస్తుంది, పొలాలను బ్లాక్‌లుగా విభజిస్తుంది, పొలానికి సరిపోయేలా పివట్‌లను ఉంచుతుంది, పైపులు మరియు వాల్వ్‌ల మార్గం వేస్తుంది, పంపు మరియు నీటి వనరు స్థానాలను నిర్ణయిస్తుంది, డిజైన్‌ను నడుపుతుంది, హెచ్చరికలను సరిచేస్తుంది, ఖర్చు తగ్గేలా డిజైన్‌ను అనుకూలీకరిస్తుంది; ఆ తర్వాత సాంకేతిక నివేదికను రాసి, కొటేషన్‌ను సిద్ధం చేస్తుంది.',
    ),
    (
      'స్థలాన్ని చూస్తుంది',
      'చిరునామా ఆధారంగా స్థలాన్ని కనుగొంటుంది, జియోరిఫరెన్స్ చేసిన ప్రాజెక్టు ఉపగ్రహ చిత్రాన్ని మరియు భూభాగాన్ని (హిల్‌షేడ్, కాంటూర్లు, వాలు, ప్రొఫైల్‌లు) చూస్తుంది, మీరు జత చేసే డ్రాయింగ్‌లు మరియు GIS ఫైళ్లను చదువుతుంది, PDF డేటా షీట్ నుండి కేటలాగ్ అంశాలను జోడిస్తుంది. చిత్రంపై పొలాల హద్దులను స్వయంగా గీస్తుంది, మీరు మ్యాప్‌పై గుర్తించిన బిందువులు, గీతలను అనుసరిస్తుంది, GPS ఉన్న పొలం ఫోటోలను అవి తీసిన చోటే డ్రాయింగ్‌పై పెడుతుంది.',
    ),
    (
      'వివరిస్తుంది, తనిఖీ చేస్తుంది',
      'ప్రాజెక్టు మరియు దాని ఫలితాల గురించి ప్రశ్నలకు సమాధానాలు ఇస్తుంది, ప్రతి డిజైన్ సందేశాన్ని, దాన్ని ఎలా సరిచేయాలో వివరిస్తుంది, విశ్లేషణలను నడుపుతుంది, ప్రాజెక్టులోనే చేయాల్సిన పనుల జాబితాను మరియు మీ నిర్ణయాల గమనికలను ఉంచుతుంది. అడిగితే ఏమీ మార్చకుండా మొత్తం డిజైన్‌ను సమీక్షిస్తుంది, ఎగుమతి చేసే ముందు షీట్‌ను చూస్తుంది.',
    ),
    (
      'మీ కీ, మీ నియంత్రణ',
      'మీ సొంత API కీతో, అగ్ర, మధ్యస్థ మరియు వేగవంతమైన శ్రేణుల్లోని Claude (Anthropic) లేదా GPT (OpenAI) మోడల్‌లను మధ్యలో ఏ సర్వర్ లేకుండా నేరుగా బ్రౌజర్ నుండే వాడుతుంది. చదవడం మాత్రమే, ముందు ప్రణాళిక, ప్రతి మార్పుకు ముందు అడగడం లేదా స్వయంచాలకంగా వర్తింపజేయడం అనే మోడ్‌లు, ప్రతి పనికి దశల పరిమితి మరియు ఖర్చు పరిమితి, ప్రతి సమాధానాన్నీ రద్దు చేసే వీలు; మీరు “పంపించు” నొక్కే వరకు ఏదీ పంపబడదు.',
    ),
  ],
  aiCta: 'AI అసిస్టెంట్‌ను తెరవండి',
  featuresTitle: 'OpenCADIrrigation ఏమి చేస్తుంది',
  features: [
    (
      'AI అసిస్టెంట్',
      'ఐచ్ఛికం: ప్రాజెక్టు గురించి AI ని అడగండి, లేదా గీయడం, డిజైన్ చేయడం దానికే అప్పగించండి. ఉపగ్రహ చిత్రాన్ని మరియు భూభాగాన్ని చూస్తూ ఇది స్ప్రింక్లర్లను, డ్రిప్‌ను అమరుస్తుంది, పొలాలను విభజిస్తుంది, పైపుల మార్గం వేస్తుంది, సైజింగ్‌ను మరియు ఆటోమేటిక్ సాధనాలను నడుపుతుంది. ఇది Claude (Anthropic) లేదా GPT (OpenAI) మోడల్‌లను మీ సొంత API కీతో, మధ్యలో ఏ సర్వర్ లేకుండా నేరుగా బ్రౌజర్ నుండే వాడుతుంది. మీరు “పంపించు” నొక్కే ముందు ఏదీ పంపబడదు, ప్రతి మార్పు మీ ఆమోదం కోసం వేచి ఉంటుంది (లేదా మీరు ఎంచుకుంటే స్వయంచాలకంగా వర్తిస్తుంది), దాన్ని రద్దు కూడా చేయవచ్చు.',
    ),
    (
      'ఆటోమేటిక్ డిజైన్ మరియు సైజింగ్',
      'ఒక్క క్లిక్‌తో లేటరల్ బ్లాక్‌లు మరియు స్ప్రింక్లర్ గ్రిడ్‌లు, సమతుల్య వర్షపాతంతో స్ప్రింక్లర్ లేఅవుట్, ప్రవాహం ప్రకారం జోన్ విభజన, పైపులు మరియు వాల్వ్‌ల మార్గం వేయడం, పొలాన్ని బ్లాక్‌లుగా విభజించడం, పొలానికి పివట్‌ను అమర్చడం మరియు వైమానిక చిత్రాల్లో వృక్షసంపద గుర్తింపు; ఎమిటర్ల పీడన పరిధి మరియు పైపుల పీడన తరగతిని పాటిస్తూ, పైపు ఖర్చు మరియు శక్తి మధ్య సమతుల్యతతో లీనియర్ ప్రోగ్రామింగ్ ద్వారా పైపుల సైజింగ్.',
    ),
    (
      'పూర్తి CAD డ్రాయింగ్',
      'గీతలు, పాలీలైన్‌లు, చాపాలు, స్ప్లైన్‌లు, హ్యాచ్‌లు, కొలతలు, పాఠ్యం, లేయర్లు మరియు బ్లాక్‌లు, టైప్ చేసిన నిర్దేశాంకాలు, స్నాప్, ధ్రువీయ ట్రాకింగ్, గ్రిప్‌లు, పునర్విమర్శ మేఘాలు మరియు CAD ప్రోగ్రాముల తరహా షార్ట్‌కట్‌లతో (L, PL, C, D, ZE…).',
    ),
